package com.machinefault.api.api;
import com.machinefault.api.api.ApiModels.*; import com.machinefault.api.domain.AppUser; import com.machinefault.api.domain.UserRole; import com.machinefault.api.repo.UserRepository; import com.machinefault.api.service.UserPresence; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
// Account administration routes. The class-level rule protects every route below by default.
@RestController @RequestMapping("/api/users") @PreAuthorize("hasAuthority('SYSTEM_ADMINISTRATOR')") public class UserController {
 private final UserRepository users;private final PasswordEncoder passwords;private final UserPresence presence;public UserController(UserRepository u,PasswordEncoder p,UserPresence presence){users=u;passwords=p;this.presence=presence;}
 @GetMapping public List<UserView> list(){return users.findAll().stream().map(UserView::of).toList();}
 @PostMapping public ResponseEntity<UserView> create(@Valid @RequestBody CreateUser body){if(users.findByUsername(body.username()).isPresent())throw new IllegalArgumentException("Username already exists.");if(users.findByEmail(body.email()).isPresent())throw new IllegalArgumentException("Email address already exists.");return ResponseEntity.status(201).body(UserView.of(users.save(new AppUser(body.username(),body.displayName(),body.email(),passwords.encode(body.password()),body.role()))));}
 @PatchMapping("/{id}") public UserView update(@PathVariable Long id,@Valid @RequestBody UpdateUser body){AppUser user=users.findById(id).orElseThrow(()->new NoSuchElementException("User not found."));users.findByEmail(body.email()).filter(existing->!existing.getId().equals(id)).ifPresent(existing->{throw new IllegalArgumentException("Email address already exists.");});user.updateProfile(body.displayName(),body.email());return UserView.of(users.save(user));}
 @GetMapping("/technicians") @PreAuthorize("hasAnyAuthority('MAINTENANCE_SUPERVISOR','MAINTENANCE_MANAGER','SYSTEM_ADMINISTRATOR')") public List<UserView> technicians(){return users.findByRole(UserRole.MAINTENANCE_TECHNICIAN).stream().filter(u->presence.isOnline(u.getId())).map(UserView::of).toList();}
}
